changeSet.sql:
    CREATE OR REPLACE FUNCTION set_updated_at()
    RETURNS TRIGGER AS $BODY$
BEGIN
      NEW.updated_at = now();
RETURN NEW;
END;
$BODY$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_set_updated_at_configuration ON configuration;
CREATE TRIGGER trigger_set_updated_at_configuration
    BEFORE UPDATE
    ON configuration
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS trigger_set_updated_at_configuration_translation ON configuration_translation;
CREATE TRIGGER trigger_set_updated_at_configuration_translation
    BEFORE UPDATE
    ON configuration_translation
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();
